changeSet.sql:
ALTER TABLE workspace_account_membership
    ADD CONSTRAINT ck_workspace_account_membership_role CHECK (role IN ('OWNER', 'ADMIN', 'MEMBER')),
    ADD CONSTRAINT ck_workspace_account_membership_source CHECK (source IN ('MANUAL', 'SCM', 'DIRECTORY', 'MIGRATED'));
ALTER TABLE login_provider DROP CONSTRAINT ck_login_provider_type;
ALTER TABLE login_provider ADD CONSTRAINT ck_login_provider_type CHECK (type IN ('GITHUB', 'GITLAB', 'SLACK', 'OUTLINE', 'OIDC'));
